<style>
.da{direction:rtl;color:#433b32;max-width:1500px;margin:auto;font-family:Tajawal,sans-serif}
.da *{box-sizing:border-box}.da h1{font-size:30px;margin:0 0 5px}.da h2{font-size:18px;margin:0 0 18px}.da p{margin:6px 0;color:#887d70}
.da-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.da-badge{background:#eee5d6;color:#8c6c40;border-radius:20px;padding:8px 15px;font-size:13px}
.da-actions{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.da button,.da .da-btn{font:inherit;cursor:pointer;border:1px solid #ded5c7;background:#fff;color:#594833;border-radius:10px;padding:10px 17px;text-decoration:none;display:inline-block}
.da .da-primary{background:#a58b65;color:#fff;border-color:#a58b65}.da .da-danger{color:#ae4e4e;border-color:#ecd5d5}.da button:hover,.da .da-btn:hover{filter:brightness(.97)}
.da-panel{background:#fff;border:1px solid #e9e2d8;border-radius:16px;padding:22px;margin-bottom:20px;box-shadow:0 3px 15px #5e4a2a05}
.da-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.da label{display:flex;flex-direction:column;gap:7px;font-size:13px;color:#786b5a}
.da input,.da select,.da textarea{font:inherit;min-width:0;width:100%;border:1px solid #e4ddd2;background:#fdfcf9;border-radius:9px;padding:10px;color:#433b32}
.da textarea{resize:vertical;min-height:85px}.da input:focus,.da select:focus,.da textarea:focus{outline:2px solid #cfbc9c;outline-offset:1px}
.da-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:20px 0}.da-stat{background:#fff;border:1px solid #e9e2d8;border-radius:14px;padding:20px;min-height:130px}
.da-stat:first-child{background:#f4eee4;border-color:#dac9ad}.da-stat span{color:#897c6a;font-size:13px}.da-stat strong{display:block;margin:12px 0 5px;font-size:26px;font-weight:800;overflow-wrap:anywhere}.da-stat small{color:#8b7d69}
.da-two{display:grid;grid-template-columns:1fr 1fr;gap:20px}.da-table-wrap{overflow:auto}.da table{width:100%;border-collapse:collapse;text-align:right}.da th{color:#8b795f;background:#f9f6f0;font-size:13px;font-weight:500}.da td,.da th{padding:13px 12px;border-bottom:1px solid #f0ebe4;vertical-align:middle}
.da .da-ledger{min-width:960px}.da .da-money{direction:ltr;unicode-bidi:isolate;white-space:nowrap;font-weight:700}.da td a{color:#947645;text-decoration:none}.da-row-actions{display:flex;gap:6px}.da-row-actions button,.da-row-actions .da-btn{padding:6px 10px;font-size:12px}
.da-empty{text-align:center;padding:38px!important;color:#9a8b75}.da-chart{height:300px;position:relative}.da-subscroll{max-height:400px;overflow:auto}
.da-dialog{width:min(620px,95vw);max-height:90vh;overflow:auto;border:1px solid #e4dbce;border-radius:18px;padding:26px;color:#433b32}
.da-dialog::backdrop{background:#30271955;backdrop-filter:blur(3px)}.da-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.da-wide{grid-column:1/-1}.da-alert{padding:14px;border-radius:10px;background:#edf6ee;color:#356547;margin-bottom:15px}.da-errors{background:#fff0ee;color:#a14c41}
.da-pagination{display:flex;align-items:center;justify-content:space-between;margin-top:18px;gap:10px;flex-wrap:wrap}.da-pagination a{color:#8c6c40;text-decoration:none}.da-note{max-width:300px;overflow-wrap:anywhere;white-space:pre-wrap}
@media(max-width:1100px){.da-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.da-two{grid-template-columns:1fr}}
@media(max-width:650px){.da-stats,.da-grid,.da-form-grid{grid-template-columns:1fr}.da-panel{padding:15px}.da-head{align-items:flex-start;gap:10px}.da h1{font-size:25px}.da-badge{display:none}.da-actions>*{flex:1;text-align:center}.da-stat{min-height:110px}.da-two{gap:0}}
</style>
